INSERT INTO _nft_ordinals_depth_wave_d_0103 (slug, canonical_profile) VALUES ('art-blocks-generative-art', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:art-blocks-generative-art","type":"nft_collection","slug":"art-blocks-generative-art","name":"Art Blocks / onchain generative art","aliases":[]},"classification":{"subtype":"generative-art platform and protocol","tags":["ethereum","generative_art","artist_platform","primary_mints","secondary_marketplace"],"chains":["Ethereum"],"jurisdictions":["United States"]},"status":{"operating_state":"active_artist_platform_with_current_programming","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:status"]},"outcome":{"label":"durable_category_leader_with_unverified_current_market_economics","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:art-blocks-generative-art:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Art Blocks is an Ethereum-based platform and protocol for artists who write an algorithm and collectors who mint a unique output from that code. The platform is not one NFT collection: each artist project has its own supply, pricing and market history, while Art Blocks supplies contracts, curation, discovery and mint infrastructure. Its onchain-generator work also gives projects a standardized way to preserve or reconstruct outputs without treating every external marketplace listing as platform revenue.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:what_it_is:1","claim:art-blocks-generative-art:section:what_it_is:2","claim:art-blocks-generative-art:section:what_it_is:3"]},"what_happened":{"body":"Art Blocks launched in 2020 and became an early home for long-form generative art during the 2021 NFT expansion. Independent reporting described hundreds of artists using the platform and documented strong demand for individual releases, but those historical auctions do not measure the whole platform today. By 2026 Art Blocks was still publishing exhibitions, artist features and creator pathways, showing continuing cultural and operating activity even though this review found no audited current revenue or platform-wide trading series.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:what_happened:1","claim:art-blocks-generative-art:section:what_happened:2","claim:art-blocks-generative-art:section:what_happened:3"]},"why_this_outcome":{"body":"Art Blocks built around a durable creative method rather than a single character brand: artist-authored code, provable scarcity and a reveal at mint. That differentiated product attracted artists and collectors before generative art became a broad NFT category, as TIME documented in 2021. The platform then kept investing in curation, creator tooling and exhibitions after speculative volumes fell. This supports cultural durability, but it does not prove that current mints, secondary royalties or platform operations are profitable.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:why_this_outcome:1","claim:art-blocks-generative-art:section:why_this_outcome:2","claim:art-blocks-generative-art:section:why_this_outcome:3"]},"strategic_choices":{"body":"Art Blocks chose a curated platform model with multiple creator tracks instead of issuing one house collection as the entire product. It also chose reusable Ethereum contracts and onchain rendering standards, making provenance and preservation part of the pitch. More recently it has used physical exhibitions and editorial storytelling to reach beyond crypto-native trading. Those choices strengthen institutional legibility, but dependence on artist quality, Ethereum economics and collector demand remains outside the platform’s full control.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:strategic_choices:1","claim:art-blocks-generative-art:section:strategic_choices:2","claim:art-blocks-generative-art:section:strategic_choices:3"]},"operating_model":{"body":"Artists submit or develop projects through Art Blocks offerings, then collectors mint algorithmically generated works through project contracts. Art Blocks provides curation, technical infrastructure and discovery; artists provide the code and creative concept; collectors own the resulting tokens. Secondary marketplaces can list those tokens, but a marketplace’s volume belongs to the project and venue before it says anything about Art Blocks itself. Current staffing, runway, mint cadence and customer cohort retention were not disclosed in the reviewed material.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:operating_model:1","claim:art-blocks-generative-art:section:operating_model:2","claim:art-blocks-generative-art:section:operating_model:3"]},"token_and_value_capture":{"body":"Art Blocks does not present a native fungible platform token in the reviewed sources. Value can be created through primary mints and creator royalties supported by contract standards, but the split among artist, platform and collaborators varies by project and must be checked at the contract or offering level. Owning one artwork does not confer equity in Art Blocks, rights to other artists’ projects or a guaranteed royalty stream. Current platform take rates and realized annual revenue are not publicly verified here.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:token_and_value_capture:1","claim:art-blocks-generative-art:section:token_and_value_capture:2","claim:art-blocks-generative-art:section:token_and_value_capture:3"]},"counterfactual":{"body":"Art Blocks would have been more fragile if it had remained only a 2021 mint calendar with no preservation layer, artist pipeline or institutional programming. The opposite risk is over-curation: a closed gate can reduce experimentation and push creators to cheaper open tools. A stronger outcome would pair cultural programming with transparent platform-level operating measures such as active artists, primary collectors, repeat mint participation and realized fee revenue. None of those counterfactual measures is yet complete in this dossier.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:counterfactual:1","claim:art-blocks-generative-art:section:counterfactual:2","claim:art-blocks-generative-art:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The largest risk is confusing famous historical collections with current platform health: a past auction or a high floor is not recurring revenue. Ethereum transaction costs, optional royalty enforcement, artist concentration and reduced speculative demand can all weaken economics even when the art remains culturally important. This review could not verify company profitability, treasury, staff count, retained collectors, current primary-mint sell-through or platform-wide secondary revenue. Those gaps keep the outcome confidence at medium.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:risks_and_unknowns:1","claim:art-blocks-generative-art:section:risks_and_unknowns:2","claim:art-blocks-generative-art:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Art Blocks progressed from a 2020 experiment to a category-defining 2021 platform, then into a post-boom institution that still supports artists and exhibitions. The important lifecycle distinction is that individual projects can be dead, dormant or liquid while the platform remains active. As of August 3, 2026 the operating platform is active and culturally durable, but current financial strength is unclassified. That is a stronger conclusion than “thriving” based on reputation alone and a more accurate one than treating lower NFT volume as platform death.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:lifecycle:1","claim:art-blocks-generative-art:section:lifecycle:2","claim:art-blocks-generative-art:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Art Blocks remains an important generative-art institution and active creator platform, while commercial performance varies sharply by artist and project. Watch primary release cadence, unique and repeat minters, active artists, exhibition partnerships, contract upgrades, realized royalty payments and platform disclosures. The call improves if current cohorts and fee revenue show repeat demand beyond a few marquee names. It weakens if new projects stop attracting collectors, current programming thins or preservation tooling becomes detached from artist adoption.","as_of":"2026-08-03","claim_ids":["claim:art-blocks-generative-art:section:outlook_and_watch:1","claim:art-blocks-generative-art:section:outlook_and_watch:2","claim:art-blocks-generative-art:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:art-blocks-generative-art:launch","type":"platform_launch","date":"2020-11-27","date_precision":"day","description":"Art Blocks published its founding account of launching an on-demand generative-art platform.","claim_ids":["claim:art-blocks-generative-art:event:launch"]},{"id":"event:art-blocks-generative-art:market-expansion","type":"category_expansion","date":"2021-10-15","date_precision":"day","description":"TIME documented hundreds of generative artists finding a home on Art Blocks during the NFT-art expansion.","claim_ids":["claim:art-blocks-generative-art:event:market-expansion"]},{"id":"event:art-blocks-generative-art:current-programming","type":"current_operations","date":"2026-04-02","date_precision":"day","description":"Art Blocks published current exhibition programming tied to Art Basel Hong Kong.","claim_ids":["claim:art-blocks-generative-art:event:current-programming"]}],"sources":[{"id":"source:art-blocks-generative-art:about","title":"About Art Blocks","url":"https://www.artblocks.io/articles/about-art-blocks","publisher":"Art Blocks","published_at":"2020-11-27","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://www.artblocks.io/articles/about-art-blocks","content_hash":null,"independence_group":"art-blocks","access_method":"direct_http","direct_http_status":200},{"id":"source:art-blocks-generative-art:offerings","title":"Art Blocks creative offerings","url":"https://docs.artblocks.io/creator-onboarding/offerings/","publisher":"Art Blocks","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://docs.artblocks.io/creator-onboarding/offerings/","content_hash":null,"independence_group":"art-blocks","access_method":"direct_http","direct_http_status":200},{"id":"source:art-blocks-generative-art:contracts","title":"Art Blocks core contract and royalty standard","url":"https://docs.artblocks.io/developer/core-contract/","publisher":"Art Blocks","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://docs.artblocks.io/developer/core-contract/","content_hash":null,"independence_group":"art-blocks","access_method":"direct_http","direct_http_status":200},{"id":"source:art-blocks-generative-art:generator","title":"Art Blocks on-chain generator","url":"https://docs.artblocks.io/protocol/on-chain-generator/","publisher":"Art Blocks","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://docs.artblocks.io/protocol/on-chain-generator/","content_hash":null,"independence_group":"art-blocks","access_method":"direct_http","direct_http_status":200},{"id":"source:art-blocks-generative-art:journal","title":"The Art Blocks Journal","url":"https://www.artblocks.io/articles","publisher":"Art Blocks","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://www.artblocks.io/articles","content_hash":null,"independence_group":"art-blocks","access_method":"direct_http","direct_http_status":200},{"id":"source:art-blocks-generative-art:time","title":"As the NFT market explodes again, artists fend off old art-world power structures","url":"https://time.com/6106679/nft-art-rise/","publisher":"TIME","published_at":"2021-10-15","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://time.com/6106679/nft-art-rise/","content_hash":null,"independence_group":"time","access_method":"indexed_browser_snapshot","direct_http_status":406}],"claims":[{"id":"claim:art-blocks-generative-art:status","field_path":"status.operating_state","assertion":"Art Blocks maintained current editorial and exhibition programming and documented active creator offerings as of August 3, 2026.","value":"active_artist_platform_with_current_programming","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Current creator documentation and dated 2026 journal entries.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:outcome","field_path":"outcome.label","assertion":"Art Blocks has endured as a recognizable onchain generative-art platform, while current company revenue and collection-level liquidity remain unverified.","value":"durable_category_leader_with_unverified_current_market_economics","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal","source:art-blocks-generative-art:time"],"evidence_locator":"Operating platform evidence plus independent historical category reporting; financial unknowns are explicit.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Art Blocks lets artists publish generative projects whose outputs are created when collectors mint.","value":"Art Blocks lets artists publish generative projects whose outputs are created when collectors mint.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:offerings"],"evidence_locator":"Platform description and creator-offering documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Each Art Blocks artist project is economically and artistically distinct from the Art Blocks platform.","value":"Each Art Blocks artist project is economically and artistically distinct from the Art Blocks platform.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:time"],"evidence_locator":"Offering categories and independent description of artist projects.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"The onchain generator provides shared rendering infrastructure without making third-party asking prices Art Blocks revenue.","value":"The onchain generator provides shared rendering infrastructure without making third-party asking prices Art Blocks revenue.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:generator","source:art-blocks-generative-art:contracts"],"evidence_locator":"Protocol documentation and metric boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Art Blocks launched in 2020 as an on-demand generative-art platform.","value":"Art Blocks launched in 2020 as an on-demand generative-art platform.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:time"],"evidence_locator":"Launch history and independent contemporary reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Demand for individual Art Blocks releases was substantial during the 2021 NFT expansion.","value":"Demand for individual Art Blocks releases was substantial during the 2021 NFT expansion.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:time"],"evidence_locator":"Contemporary reporting on artists and auctions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Current programming continued in 2026, but audited platform revenue and a complete current trading series were not published in reviewed sources.","value":"Current programming continued in 2026, but audited platform revenue and a complete current trading series were not published in reviewed sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:journal","source:art-blocks-generative-art:offerings"],"evidence_locator":"Current journal and documentation review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"Code-based creation and the collector-triggered reveal differentiated Art Blocks from fixed-image collectible drops.","value":"Code-based creation and the collector-triggered reveal differentiated Art Blocks from fixed-image collectible drops.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:generator","source:art-blocks-generative-art:time"],"evidence_locator":"Product mechanism and independent category reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"Creator offerings and current editorial programming show the platform continued beyond its 2021 market peak.","value":"Creator offerings and current editorial programming show the platform continued beyond its 2021 market peak.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Current operating surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"The evidence supports cultural durability but does not establish current profitability.","value":"The evidence supports cultural durability but does not establish current profitability.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:journal","source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:time"],"evidence_locator":"Synthesis across current first-party and independent historical evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Art Blocks offers multiple creator pathways rather than treating every project as one undifferentiated collection.","value":"Art Blocks offers multiple creator pathways rather than treating every project as one undifferentiated collection.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings"],"evidence_locator":"Creator-offering documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"The platform invested in reusable contracts and an onchain rendering standard.","value":"The platform invested in reusable contracts and an onchain rendering standard.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:generator"],"evidence_locator":"Developer and protocol documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"Exhibitions and editorial programming extend distribution beyond marketplace trading.","value":"Exhibitions and editorial programming extend distribution beyond marketplace trading.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:journal"],"evidence_locator":"Dated exhibition and artist features.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Artists supply project code and collectors mint generated outputs through the platform’s contract system.","value":"Artists supply project code and collectors mint generated outputs through the platform’s contract system.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:contracts"],"evidence_locator":"Creator onboarding and core-contract documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Collection trading on an external venue is not the same measure as Art Blocks platform usage or revenue.","value":"Collection trading on an external venue is not the same measure as Art Blocks platform usage or revenue.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:time"],"evidence_locator":"Platform and market boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Current staffing, runway, mint cadence and retained collector cohorts were not disclosed.","value":"Current staffing, runway, mint cadence and retained collector cohorts were not disclosed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Reviewed current public surfaces.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"The reviewed Art Blocks materials do not describe a native fungible platform token.","value":"The reviewed Art Blocks materials do not describe a native fungible platform token.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:contracts"],"evidence_locator":"Platform and contract documentation.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Core contracts support royalty information, while project economics can vary by deployment.","value":"Core contracts support royalty information, while project economics can vary by deployment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:offerings"],"evidence_locator":"Royalty standard and offering differences.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"An Art Blocks token is artwork ownership, not equity in the platform or a guaranteed income claim.","value":"An Art Blocks token is artwork ownership, not equity in the platform or a guaranteed income claim.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:time"],"evidence_locator":"Contract and ownership boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"Creator programs, protocol work and exhibitions give Art Blocks more than one operating surface.","value":"Creator programs, protocol work and exhibitions give Art Blocks more than one operating surface.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:generator","source:art-blocks-generative-art:journal"],"evidence_locator":"Current product and distribution surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"A curated model trades quality control for a narrower creator funnel.","value":"A curated model trades quality control for a narrower creator funnel.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:offerings"],"evidence_locator":"Offering design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Active-artist cohorts, repeat collectors and realized platform fee revenue remain unverified.","value":"Active-artist cohorts, repeat collectors and realized platform fee revenue remain unverified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal","source:art-blocks-generative-art:contracts"],"evidence_locator":"Public evidence review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Historical project prices do not by themselves measure current platform health.","value":"Historical project prices do not by themselves measure current platform health.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:time","source:art-blocks-generative-art:journal"],"evidence_locator":"Historical-versus-current evidence boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Royalty standards can communicate payment information but do not guarantee every venue enforces payment.","value":"Royalty standards can communicate payment information but do not guarantee every venue enforces payment.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:contracts"],"evidence_locator":"ERC-2981 implementation context.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Profitability, treasury, staffing, retained collectors and current sell-through were not verified.","value":"Profitability, treasury, staffing, retained collectors and current sell-through were not verified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Current-source review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"Art Blocks launched in 2020 and gained broad artist and collector attention during 2021.","value":"Art Blocks launched in 2020 and gained broad artist and collector attention during 2021.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:about","source:art-blocks-generative-art:time"],"evidence_locator":"Launch and independent historical reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"Current creator documentation and 2026 programming show continued platform operations.","value":"Current creator documentation and 2026 programming show continued platform operations.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Current operating evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Current financial strength remains unclassified because verified platform economics were not found.","value":"Current financial strength remains unclassified because verified platform economics were not found.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:journal"],"evidence_locator":"Financial evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Current creator and exhibition surfaces support a continuing operating base case.","value":"Current creator and exhibition surfaces support a continuing operating base case.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Current first-party activity.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"Project-level demand must be measured separately from platform-level retention and revenue.","value":"Project-level demand must be measured separately from platform-level retention and revenue.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:art-blocks-generative-art:contracts","source:art-blocks-generative-art:time"],"evidence_locator":"Metric boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Repeat-minter cohorts, active-artist counts and realized fee revenue need current verification.","value":"Repeat-minter cohorts, active-artist counts and realized fee revenue need current verification.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:art-blocks-generative-art:offerings","source:art-blocks-generative-art:journal"],"evidence_locator":"Forward evidence requirements.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:event:launch","field_path":"events[event:art-blocks-generative-art:launch]","assertion":"Art Blocks published its founding account of launching an on-demand generative-art platform.","value":"2020-11-27","as_of":"2020-11-27","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:about"],"evidence_locator":"Dated About Art Blocks article.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:event:market-expansion","field_path":"events[event:art-blocks-generative-art:market-expansion]","assertion":"TIME documented hundreds of generative artists finding a home on Art Blocks during the NFT-art expansion.","value":"2021-10-15","as_of":"2021-10-15","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:time"],"evidence_locator":"Independent contemporary feature.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:art-blocks-generative-art:event:current-programming","field_path":"events[event:art-blocks-generative-art:current-programming]","assertion":"Art Blocks published current exhibition programming tied to Art Basel Hong Kong.","value":"2026-04-02","as_of":"2026-04-02","confidence":"high","kind":"fact","source_ids":["source:art-blocks-generative-art:journal"],"evidence_locator":"Dated journal entry visible in the current journal.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:07:00Z","next_review_at":"2026-08-10T22:07:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["platform_revenue","profitability","treasury","staffing","active_artists","repeat_minters","primary_sell_through","realized_royalties"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Art Blocks the platform, individual artist projects, token holders, external marketplaces and the company behind the platform are separate analytical objects.","metric_boundary":"Project floors, primary auction proceeds, marketplace volume, royalties and platform revenue are distinct measures and are never substituted for one another.","editorial_guardrail":"Do not call Art Blocks financially thriving from historic auction prices or current cultural programming alone.","explicit_unknowns":["platform_revenue","profitability","treasury","staffing","active_artists","repeat_minters","primary_sell_through","realized_royalties"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","Platform lifecycle is evaluated separately from the lifecycle of each artist collection hosted on it."]}}');

INSERT INTO _nft_ordinals_depth_wave_d_0103 (slug, canonical_profile) VALUES ('mad-lads', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:mad-lads","type":"nft_collection","slug":"mad-lads","name":"Mad Lads","aliases":[]},"classification":{"subtype":"profile-picture and xNFT collection","tags":["solana","xnft","backpack","holder_allocation","operator_ecosystem"],"chains":["Solana"],"jurisdictions":["United States","United Arab Emirates"]},"status":{"operating_state":"active_collection_inside_active_backpack_ecosystem","as_of":"2026-08-03","claim_ids":["claim:mad-lads:status"]},"outcome":{"label":"durable_operator_linked_collection_with_one_time_token_benefit","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:mad-lads:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Mad Lads is a 10,000-piece Solana profile-picture collection created by the team behind Backpack and introduced as an xNFT, a token that could expose applications inside the Backpack wallet. It is not the Backpack company, exchange, wallet or BP token. The shared operator gives the collection privileged cultural positioning and occasional benefits, but an NFT does not represent equity, customer assets or a contractual share of exchange revenue. Any holder program must be verified on its own terms and snapshot date.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:what_it_is:1","claim:mad-lads:section:what_it_is:2","claim:mad-lads:section:what_it_is:3"]},"what_happened":{"body":"Heavy demand and bot traffic forced the April 2023 mint to be delayed, while the team used a decoy mint and refunds to blunt automated abuse. Mad Lads then became the cultural entry point for Backpack as the operator expanded from wallet and xNFT infrastructure into a regulated exchange business. Backpack’s 2026 token launch reserved a defined share for eligible Mad Lads holders and published a snapshot-based claim process. That distribution was a dated event, not evidence of a permanent rewards obligation.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:what_happened:1","claim:mad-lads:section:what_happened:2","claim:mad-lads:section:what_happened:3"]},"why_this_outcome":{"body":"Mad Lads benefited from unusually tight product and community fit: the collection gave Backpack a recognizable user group, and Backpack gave holders a live wallet, exchange and distribution channel. Independent reporting also found that the founders’ credibility in Solana and the timing after FTX’s collapse helped the launch attract attention. The 2026 BP allocation renewed that link. The inference is durable relevance, not guaranteed value: operator growth can support attention while NFT liquidity, holder retention and realized benefits still vary.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:why_this_outcome:1","claim:mad-lads:section:why_this_outcome:2","claim:mad-lads:section:why_this_outcome:3"]},"strategic_choices":{"body":"The team launched a collectible as a live demonstration of its xNFT wallet thesis instead of treating the art as a disconnected merchandise drop. It used bot countermeasures and refunds during a hostile mint, then made Mad Lads a recurring community layer around Backpack products. In 2026 Backpack chose a snapshot-based BP allocation for holders, which rewarded a specific cohort without making benefits transferable after the snapshot. This strategy aligns attention with the operator, but it also makes collection sentiment dependent on Backpack execution and policy.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:strategic_choices:1","claim:mad-lads:section:strategic_choices:2","claim:mad-lads:section:strategic_choices:3"]},"operating_model":{"body":"The collection itself is a fixed-supply digital collectible, while Backpack operates the wallet, exchange and related services. Holders can use the NFT as identity and may receive access or benefits chosen by the operator or third parties. Backpack acquires customers and earns through its own products; those economics do not automatically accrue to the NFT. Current verified collection staffing, royalty receipts, unique active holders and repeat marketplace buyers were not published in the reviewed sources, so operating health is inferred from active surfaces rather than a complete P&L.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:operating_model:1","claim:mad-lads:section:operating_model:2","claim:mad-lads:section:operating_model:3"]},"token_and_value_capture":{"body":"Mad Lads holders own the NFT; Backpack’s BP is a separate fungible token. Backpack’s official TGE overview allocated 1 percent of BP supply to Mad Lads holders, and its claim guide tied eligibility to a historical wallet snapshot. That was a one-time allocation, not recurring NFT yield, and transferring the NFT after the snapshot did not transfer the allocation. This review found no contract promising holders exchange profits, future airdrops or a permanent share of token supply, and it does not value the BP received.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:token_and_value_capture:1","claim:mad-lads:section:token_and_value_capture:2","claim:mad-lads:section:token_and_value_capture:3"]},"counterfactual":{"body":"Mad Lads could have become another isolated profile-picture mint if Backpack had not shipped usable products or survived the loss of capital associated with FTX. The team instead kept building a wallet and exchange, preserving a reason for the collection to matter beyond launch week. A better outcome for holders would include transparent, repeatable benefits and current liquidity data that are not dependent on occasional announcements. A worse outcome would follow regulatory trouble, exchange loss events or policy changes that sever the collection’s privileged relationship with the operator.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:counterfactual:1","claim:mad-lads:section:counterfactual:2","claim:mad-lads:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Mad Lads is exposed to Backpack concentration risk: security, solvency, regulation, service availability and management decisions can affect collection sentiment even when the NFT contracts continue to exist. The xNFT label also should not be read as proof that holders still use embedded applications. Marketplace floors can be thin and volatile, and the BP allocation can create short-lived attention that is mistaken for retained demand. This review could not verify current holder concentration, sales depth, royalty revenue, embedded-app usage or contractual future benefits.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:risks_and_unknowns:1","claim:mad-lads:section:risks_and_unknowns:2","claim:mad-lads:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Mad Lads moved from a technically ambitious and heavily contested April 2023 mint into the flagship community collection for a growing wallet and exchange operator. It retained a clear operator relationship through Backpack’s expansion and received a documented BP allocation in 2026. As of August 3, 2026 the collection is active and strategically relevant, but commercial health is only partly measured. The lifecycle call is “durable operator-linked collection,” not “thriving” solely because Backpack is active or because holders received one distribution.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:lifecycle:1","claim:mad-lads:section:lifecycle:2","claim:mad-lads:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Mad Lads remains a recognizable Solana collection and the cultural front door to Backpack, with value driven more by operator relevance than by the original xNFT novelty alone. Watch unique buyers and sellers, executable bids, holder concentration, royalty receipts, actual xNFT use, Backpack security and licensing status, and whether benefits recur under published rules. The call improves if product use and broad holder participation persist without subsidies. It weakens if activity concentrates around one-off allocations or Backpack problems spill into the collection.","as_of":"2026-08-03","claim_ids":["claim:mad-lads:section:outlook_and_watch:1","claim:mad-lads:section:outlook_and_watch:2","claim:mad-lads:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:mad-lads:mint-delay","type":"mint_event","date":"2023-04-21","date_precision":"day","description":"Heavy demand and bot activity forced the Mad Lads mint to be delayed.","claim_ids":["claim:mad-lads:event:mint-delay"]},{"id":"event:mad-lads:exchange-beta","type":"operator_expansion","date":"2024-03-19","date_precision":"day","description":"TechCrunch reported Backpack had expanded into exchange beta after surviving the loss of capital at FTX.","claim_ids":["claim:mad-lads:event:exchange-beta"]},{"id":"event:mad-lads:bp-claim","type":"holder_distribution","date":"2026-03-23","date_precision":"day","description":"Backpack opened instructions for eligible Mad Lads snapshot holders to claim BP.","claim_ids":["claim:mad-lads:event:bp-claim"]}],"sources":[{"id":"source:mad-lads:history","title":"What are the Mad Lads?","url":"https://news.madlads.com/p/what-are-the-mad-lads","publisher":"Mad News","published_at":"2023-12-22","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://news.madlads.com/p/what-are-the-mad-lads","content_hash":null,"independence_group":"mad-lads","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:collection","title":"Mad Lads collection","url":"https://www.madlads.com/","publisher":"Mad Lads","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://www.madlads.com/","content_hash":null,"independence_group":"mad-lads","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:about-backpack","title":"About Backpack","url":"https://learn.backpack.exchange/about","publisher":"Backpack","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://learn.backpack.exchange/about","content_hash":null,"independence_group":"backpack","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:tge","title":"Backpack TGE: 24% to Points, 1% to Mad Lads","url":"https://learn.backpack.exchange/blog/backpack-token-tge-overview","publisher":"Backpack","published_at":"2026-01-30","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://learn.backpack.exchange/blog/backpack-token-tge-overview","content_hash":null,"independence_group":"backpack","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:claim","title":"How to claim your BP allocation on Backpack Exchange","url":"https://learn.backpack.exchange/articles/how-to-claim-bp","publisher":"Backpack","published_at":"2026-03-23","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://learn.backpack.exchange/articles/how-to-claim-bp","content_hash":null,"independence_group":"backpack","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:coindesk-launch","title":"Heavy demand for Madlads NFT breaks internet, delays mint","url":"https://www.coindesk.com/web3/2023/04/21/heavy-demand-for-madlads-nft-breaks-internet-delays-mint","publisher":"CoinDesk","published_at":"2023-04-21","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://www.coindesk.com/web3/2023/04/21/heavy-demand-for-madlads-nft-breaks-internet-delays-mint","content_hash":null,"independence_group":"coindesk","access_method":"direct_http","direct_http_status":200},{"id":"source:mad-lads:techcrunch","title":"How Backpack climbed to success after FTX died","url":"https://techcrunch.com/2024/03/19/how-crypto-exchange-backpack-climbed-its-way-to-success-after-its-major-investor-ftx-died/","publisher":"TechCrunch","published_at":"2024-03-19","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://techcrunch.com/2024/03/19/how-crypto-exchange-backpack-climbed-its-way-to-success-after-its-major-investor-ftx-died/","content_hash":null,"independence_group":"techcrunch","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:mad-lads:status","field_path":"status.operating_state","assertion":"Mad Lads remained an active 10,000-item Solana collection tied to Backpack, with a completed BP holder-claim process documented in 2026.","value":"active_collection_inside_active_backpack_ecosystem","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:collection","source:mad-lads:about-backpack","source:mad-lads:claim"],"evidence_locator":"Current collection and operator pages plus dated claim instructions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:outcome","field_path":"outcome.label","assertion":"Mad Lads sustained relevance by anchoring Backpack’s user community, but its benefits are discretionary or event-specific rather than ownership of Backpack cash flows.","value":"durable_operator_linked_collection_with_one_time_token_benefit","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:mad-lads:history","source:mad-lads:tge","source:mad-lads:techcrunch","source:mad-lads:coindesk-launch"],"evidence_locator":"Launch evidence, operator strategy, 2026 allocation and explicit holder-right boundary.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Mad Lads is a 10,000-piece Solana collection created by the team behind Backpack.","value":"Mad Lads is a 10,000-piece Solana collection created by the team behind Backpack.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:history","source:mad-lads:collection","source:mad-lads:tge"],"evidence_locator":"Collection history and 2026 operator description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Mad Lads was introduced as an xNFT connected to applications inside Backpack.","value":"Mad Lads was introduced as an xNFT connected to applications inside Backpack.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:history","source:mad-lads:coindesk-launch"],"evidence_locator":"Product history and independent launch reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"A Mad Lads NFT is separate from Backpack equity, customer assets and the BP token.","value":"A Mad Lads NFT is separate from Backpack equity, customer assets and the BP token.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:mad-lads:about-backpack","source:mad-lads:tge"],"evidence_locator":"Entity and rights boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"The April 2023 mint was delayed after demand and bot traffic overwhelmed launch infrastructure.","value":"The April 2023 mint was delayed after demand and bot traffic overwhelmed launch infrastructure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:coindesk-launch"],"evidence_locator":"Independent launch report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Backpack expanded from wallet and xNFT products into an exchange business after the collection launched.","value":"Backpack expanded from wallet and xNFT products into an exchange business after the collection launched.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:about-backpack","source:mad-lads:techcrunch"],"evidence_locator":"Operator history and independent business profile.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Eligible snapshot holders received a defined 2026 BP allocation through a wallet-linked claim process.","value":"Eligible snapshot holders received a defined 2026 BP allocation through a wallet-linked claim process.","as_o