s":["source:mad-lads:tge","source:mad-lads:claim","source:mad-lads:techcrunch"],"evidence_locator":"Benefit mechanics and analytical boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Mad Lads was positioned as a demonstration of Backpack’s xNFT model.","value":"Mad Lads was positioned as a demonstration of Backpack’s xNFT model.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:history","source:mad-lads:coindesk-launch"],"evidence_locator":"Launch positioning.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"The launch team used a decoy mint and refunds as an anti-bot response.","value":"The launch team used a decoy mint and refunds as an anti-bot response.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:coindesk-launch"],"evidence_locator":"Independent launch report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"The BP holder allocation used a snapshot, so later NFT transfers did not transfer that claim.","value":"The BP holder allocation used a snapshot, so later NFT transfers did not transfer that claim.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:claim"],"evidence_locator":"Official claim instructions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Backpack operates wallet and exchange products separately from the Mad Lads collection.","value":"Backpack operates wallet and exchange products separately from the Mad Lads collection.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:about-backpack","source:mad-lads:techcrunch"],"evidence_locator":"Operator product description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Holder access or distributions are program-specific and do not automatically mirror Backpack revenue.","value":"Holder access or distributions are program-specific and do not automatically mirror Backpack revenue.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Benefit terms and entity boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Current royalty receipts, active holders and repeat buyer cohorts were not published.","value":"Current royalty receipts, active holders and repeat buyer cohorts were not published.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:collection","source:mad-lads:about-backpack"],"evidence_locator":"Current evidence review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"Backpack documented a 1 percent BP supply allocation for eligible Mad Lads holders.","value":"Backpack documented a 1 percent BP supply allocation for eligible Mad Lads holders.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:tge"],"evidence_locator":"Official TGE allocation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Eligibility followed a historical wallet snapshot and did not transfer with a later NFT sale.","value":"Eligibility followed a historical wallet snapshot and did not transfer with a later NFT sale.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:claim"],"evidence_locator":"Official claim instructions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"The reviewed sources do not establish recurring yield, exchange profit-sharing or guaranteed future airdrops.","value":"The reviewed sources do not establish recurring yield, exchange profit-sharing or guaranteed future airdrops.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Rights review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"Backpack continued building after losing operating capital connected to the FTX collapse.","value":"Backpack continued building after losing operating capital connected to the FTX collapse.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:techcrunch"],"evidence_locator":"Independent company history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"Live operator products gave the collection a continuing role beyond its launch.","value":"Live operator products gave the collection a continuing role beyond its launch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:mad-lads:about-backpack","source:mad-lads:history"],"evidence_locator":"Product and community linkage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Repeatable holder economics and complete current liquidity data remain unverified.","value":"Repeatable holder economics and complete current liquidity data remain unverified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:collection","source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"The collection’s brand and benefits are materially linked to Backpack’s execution.","value":"The collection’s brand and benefits are materially linked to Backpack’s execution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:history","source:mad-lads:about-backpack","source:mad-lads:tge"],"evidence_locator":"Operator linkage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"A one-time token allocation can increase attention without proving retained NFT demand.","value":"A one-time token allocation can increase attention without proving retained NFT demand.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Event-versus-retention boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Current holder concentration, sales depth, royalties and xNFT usage were not verified.","value":"Current holder concentration, sales depth, royalties and xNFT usage were not verified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:collection","source:mad-lads:about-backpack"],"evidence_locator":"Current public-source review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"Mad Lads launched in April 2023 after a high-demand, disrupted mint.","value":"Mad Lads launched in April 2023 after a high-demand, disrupted mint.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:coindesk-launch"],"evidence_locator":"Independent launch report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"The collection remained tied to Backpack through its product expansion and 2026 token event.","value":"The collection remained tied to Backpack through its product expansion and 2026 token event.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:about-backpack","source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Operator and benefit timeline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Current NFT commercial health remains only partly measured.","value":"Current NFT commercial health remains only partly measured.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:collection","source:mad-lads:techcrunch"],"evidence_locator":"Collection-versus-operator metric boundary.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"The continuing Backpack relationship supports a durable cultural base case.","value":"The continuing Backpack relationship supports a durable cultural base case.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:mad-lads:about-backpack","source:mad-lads:tge","source:mad-lads:techcrunch"],"evidence_locator":"Current operator linkage and independent context.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"One-off benefits must be separated from broad, repeated holder participation.","value":"One-off benefits must be separated from broad, repeated holder participation.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Benefit and retention boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current bids, holder concentration, royalty receipts and xNFT usage need verification.","value":"Current bids, holder concentration, royalty receipts and xNFT usage need verification.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:mad-lads:collection","source:mad-lads:about-backpack"],"evidence_locator":"Forward evidence requirements.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:event:mint-delay","field_path":"events[event:mad-lads:mint-delay]","assertion":"Heavy demand and bot activity forced the Mad Lads mint to be delayed.","value":"2023-04-21","as_of":"2023-04-21","confidence":"high","kind":"fact","source_ids":["source:mad-lads:coindesk-launch"],"evidence_locator":"Independent launch report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:event:exchange-beta","field_path":"events[event:mad-lads:exchange-beta]","assertion":"TechCrunch reported Backpack had expanded into exchange beta after surviving the loss of capital at FTX.","value":"2024-03-19","as_of":"2024-03-19","confidence":"high","kind":"fact","source_ids":["source:mad-lads:techcrunch"],"evidence_locator":"Independent company profile.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:mad-lads:event:bp-claim","field_path":"events[event:mad-lads:bp-claim]","assertion":"Backpack opened instructions for eligible Mad Lads snapshot holders to claim BP.","value":"2026-03-23","as_of":"2026-03-23","confidence":"high","kind":"fact","source_ids":["source:mad-lads:tge","source:mad-lads:claim"],"evidence_locator":"Official TGE and claim documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:07:00Z","next_review_at":"2026-08-10T22:07:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["holder_concentration","unique_buyers_and_sellers","bid_depth","royalty_revenue","xnft_usage","future_holder_benefits","collection_staffing"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Mad Lads NFTs, the Backpack company, Backpack Exchange customer assets, the Backpack wallet and the BP token are separate.","metric_boundary":"NFT floors, exchange volume, operator revenue, BP price and holder allocations are distinct and cannot substitute for one another.","editorial_guardrail":"Do not describe the 2026 BP allocation as recurring yield, Backpack equity or a benefit that followed NFT transfers after the snapshot.","explicit_unknowns":["holder_concentration","unique_buyers_and_sellers","bid_depth","royalty_revenue","xnft_usage","future_holder_benefits","collection_staffing"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","Operator strength is treated as context and distribution, not as a direct collection cash flow."]}}');

INSERT INTO _nft_ordinals_depth_wave_d_0103 (slug, canonical_profile) VALUES ('okay-bears', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:okay-bears","type":"nft_collection","slug":"okay-bears","name":"Okay Bears","aliases":[]},"classification":{"subtype":"profile-picture collection and consumer brand","tags":["solana","consumer_products","licensing","img","charity"],"chains":["Solana"],"jurisdictions":["Australia"]},"status":{"operating_state":"active_consumer_brand_with_partly_measured_nft_market","as_of":"2026-08-03","claim_ids":["claim:okay-bears:status"]},"outcome":{"label":"active_brand_extension_with_unverified_collection_retention","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:okay-bears:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Okay Bears began as a 10,000-piece Solana profile-picture collection and developed into a character and lifestyle brand. The NFT collection, the operating brand, licensed products and charitable campaigns are related but not interchangeable: a retail sale is not an NFT sale, and a licensing deal does not automatically pay token holders. Current brand pages describe apparel, partnerships and public-impact programs. They do not describe the NFT as equity, a royalty claim or a guaranteed coupon on every product.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:what_it_is:1","claim:okay-bears:section:what_it_is:2","claim:okay-bears:section:what_it_is:3"]},"what_happened":{"body":"Okay Bears minted in April 2022 and produced roughly $18 million of secondary volume in one day, briefly topping major Ethereum collections. Later that year the team signed with IMG to pursue consumer products, live events and publishing. The current brand says it subsequently worked with Zara, appeared in Fortnite promotion and raised funds for charities, while the store still lists physical products. Those milestones show brand execution, but the reviewed pages do not publish current NFT trading depth or audited brand revenue.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:what_happened:1","claim:okay-bears:section:what_happened:2","claim:okay-bears:section:what_happened:3"]},"why_this_outcome":{"body":"The collection succeeded at launch because its approachable artwork, optimistic message and Solana timing reached beyond a narrow trading niche. The team then made a deliberate licensing pivot while attention was still high, giving the characters distribution through established retail and entertainment channels. That helps explain why the brand still has a public product surface after the NFT boom. It does not prove that original holders remain engaged or that consumer revenue flows back to the collection, which is why the outcome stays mixed rather than fully thriving.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:why_this_outcome:1","claim:okay-bears:section:why_this_outcome:2","claim:okay-bears:section:why_this_outcome:3"]},"strategic_choices":{"body":"Okay Bears chose a positive, broadly licensable character identity rather than an exclusively crypto-native or adversarial brand. It hired IMG within months of launch and used partnerships, retail products and charity work to make the intellectual property visible outside NFT marketplaces. This diversified distribution and reduced dependence on a single marketplace cycle. The tradeoff is that brand success can become detached from token demand unless holders receive clear, enforceable utility or the community remains central to product launches; neither condition is fully measured here.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:strategic_choices:1","claim:okay-bears:section:strategic_choices:2","claim:okay-bears:section:strategic_choices:3"]},"operating_model":{"body":"The operating brand develops character IP, licenses it to partners, sells physical goods and runs community or charitable campaigns. NFT holders own individual Solana tokens and can participate in community identity, but the reviewed current pages do not state that they control the IP company or receive product margins. Sales through Zara or the brand store belong to those commercial relationships, not automatically to the collection’s secondary market. Current unit sales, license fees, margins, repeat customers and NFT-holder participation were not disclosed.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:operating_model:1","claim:okay-bears:section:operating_model:2","claim:okay-bears:section:operating_model:3"]},"token_and_value_capture":{"body":"The original Okay Bears NFT is the relevant onchain asset in this profile; this review found no native fungible token required to use the brand. The collection can capture value through resale demand and any creator royalties actually paid, while the operating company can capture value through licensing and product sales. Those paths are separate. Owning a bear does not, on the evidence reviewed, entitle the holder to IMG licensing revenue, Zara sales or charity funds, and current realized royalty receipts were not published.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:token_and_value_capture:1","claim:okay-bears:section:token_and_value_capture:2","claim:okay-bears:section:token_and_value_capture:3"]},"counterfactual":{"body":"Without the early IMG relationship, Okay Bears might have remained a high-volume 2022 mint whose visibility faded with Solana NFT trading. The licensing strategy preserved brand surfaces and created reasons for the characters to appear in retail, but it may also have prioritized a consumer-IP company over measurable NFT-holder value. A stronger counterfactual would publish repeat product demand, licensing results and holder participation without promising securities-like returns. A weaker path would be a dormant store and no current partners while historical launch volume carried the narrative.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:counterfactual:1","claim:okay-bears:section:counterfactual:2","claim:okay-bears:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The principal risk is brand-token decoupling: Okay Bears can sell licensed products while the original NFT loses users, buyers or relevance. Retail claims on a brand website also need independent, dated verification before they are used as financial evidence. Solana marketplace liquidity can be thin, quoted floors can move without broad trading and royalties may not be consistently enforced. This review could not verify holder concentration, current sales, bids, repeat buyers, realized royalties, licensing revenue, product margins or a formal holder-benefit program.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:risks_and_unknowns:1","claim:okay-bears:section:risks_and_unknowns:2","claim:okay-bears:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Okay Bears moved from a breakout April 2022 mint into a licensing-led consumer brand with physical products and partnership claims that remain visible in 2026. That is real operating continuity, but it answers a different question from whether the NFT collection has retained owners, liquidity and repeat use. As of August 3, 2026 the brand is active and the NFT artifact persists; collection-market health is unclassified to middling because current participation data are missing. Historical launch volume is not treated as today’s demand.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:lifecycle:1","claim:okay-bears:section:lifecycle:2","claim:okay-bears:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Okay Bears continues as a modest consumer IP brand while the original NFT community remains valuable mainly as provenance and an early audience. Watch current licensing announcements, actual product availability, repeat retail releases, active holder counts, unique marketplace buyers and sellers, executable bids, royalty receipts and any clearly documented holder access. The call improves if brand growth repeatedly includes and retains holders. It weakens if the store and partnerships persist only as stale marketing or if NFT activity concentrates in a few wallets with no new demand.","as_of":"2026-08-03","claim_ids":["claim:okay-bears:section:outlook_and_watch:1","claim:okay-bears:section:outlook_and_watch:2","claim:okay-bears:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:okay-bears:launch","type":"collection_launch","date":"2022-04-27","date_precision":"day","description":"Okay Bears recorded roughly $18 million of secondary trading during its breakout day.","claim_ids":["claim:okay-bears:event:launch"]},{"id":"event:okay-bears:img-deal","type":"licensing_deal","date":"2022-09-20","date_precision":"day","description":"CoinDesk reported that Okay Bears signed IMG for global consumer-product licensing.","claim_ids":["claim:okay-bears:event:img-deal"]},{"id":"event:okay-bears:brand-current","type":"current_operations","date":"2026-08-03","date_precision":"day","description":"Okay Bears maintained current brand and product storefront pages.","claim_ids":["claim:okay-bears:event:brand-current"]}],"sources":[{"id":"source:okay-bears:launch","title":"Okay Bears top Ethereum NFT projects in $18M sales day","url":"https://decrypt.co/98848/solana-okay-bears-top-ethereum-nft-projects-18m-sales","publisher":"Decrypt","published_at":"2022-04-27","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://decrypt.co/98848/solana-okay-bears-top-ethereum-nft-projects-18m-sales","content_hash":null,"independence_group":"decrypt","access_method":"direct_http","direct_http_status":200},{"id":"source:okay-bears:img","title":"Okay Bears signs licensing deal with IMG","url":"https://www.coindesk.com/business/