INSERT INTO _nft_ordinals_depth_wave_d_0103 (slug, canonical_profile) VALUES ('bitcoin-puppets', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"ordinals_collection:bitcoin-puppets","type":"ordinals_collection","slug":"bitcoin-puppets","name":"Bitcoin Puppets","aliases":[]},"classification":{"subtype":"meme-native profile-picture inscriptions","tags":["bitcoin","ordinals","free_mint","pseudonymous_artist","copyleft","no_roadmap"],"chains":["Bitcoin"],"jurisdictions":[]},"status":{"operating_state":"active_artifact_and_community_without_formal_roadmap","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:status"]},"outcome":{"label":"culturally_durable_meme_collection_with_thinly_measured_market","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:bitcoin-puppets:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Bitcoin Puppets is a 10,001-piece collection of hand-drawn profile-picture inscriptions on Bitcoin, created by the pseudonymous artist Le Puppeteer Fou. It was a free mint and explicitly presents itself as art and community rather than a conventional startup with a roadmap or guarantees. The collection is separate from the artist’s earlier O.P.I.U.M. work, later honorary pieces, third-party marketplaces and any adjacent fungible tokens. A marketplace can index a Puppet without becoming its operator.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:what_it_is:1","claim:bitcoin-puppets:section:what_it_is:2","claim:bitcoin-puppets:section:what_it_is:3"]},"what_happened":{"body":"The collection launched in January 2024 after the artist’s smaller O.P.I.U.M. series and became a high-profile Ordinals meme collection. nft now documented intense attention and a high quoted floor in April 2024, while later reporting described the same anti-roadmap identity in 2025. By August 2026 the community hub and gallery remained available and ORD still displayed collection listings and recent observations. Historical floors are not reused as current value, and live listings are not treated as completed sales.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:what_happened:1","claim:bitcoin-puppets:section:what_happened:2","claim:bitcoin-puppets:section:what_happened:3"]},"why_this_outcome":{"body":"Bitcoin Puppets succeeded culturally by making the absence of a normal roadmap part of the product. Handmade art, absurd humor, copyleft-style sharing and a simple “community is the project” message gave holders material to remix without waiting for a game or promised yield. Independent histories connect that identity to the artist’s earlier work, so the collection did not appear from nowhere. Current market observations show continued recognition, but not enough evidence to claim deep liquidity or a sustainable business.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:why_this_outcome:1","claim:bitcoin-puppets:section:why_this_outcome:2","claim:bitcoin-puppets:section:why_this_outcome:3"]},"strategic_choices":{"body":"The creator chose a free mint, pseudonymity, minimal formal promises and permissive remix culture. That reduced the need to fund and deliver a complex roadmap while making authenticity and community behavior the primary retention mechanism. The community hub now formalizes the story and curates the artifacts without claiming centralized control over Bitcoin. This choice protects the project from unmet product promises, but it also leaves holders without a conventional team, service-level commitment or accountable commercial plan.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:strategic_choices:1","claim:bitcoin-puppets:section:strategic_choices:2","claim:bitcoin-puppets:section:strategic_choices:3"]},"operating_model":{"body":"Bitcoin Puppets operates more like an artist-led cultural network than a company. The artist creates work, volunteers and holders maintain community surfaces, and independent marketplaces facilitate trades. Bitcoin preserves the inscription data, but it does not guarantee discovery, liquidity, moderation or a maintained website. The reviewed sources do not identify a formal entity, payroll, treasury, royalty program or recurring customer product. Marketplace rewards and lending products belong to those third parties, not to the Puppets collection.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:operating_model:1","claim:bitcoin-puppets:section:operating_model:2","claim:bitcoin-puppets:section:operating_model:3"]},"token_and_value_capture":{"body":"The Puppets inscriptions are the collection assets. This review found no native collection token or contractually promised revenue share, and the community’s own language says there are no guarantees. Adjacent names such as PUPS or Rune Pups must not be treated as collection cash flow without explicit legal and technical linkage. Holders may capture value through voluntary sales or cultural participation, while marketplaces capture their own fees. Current creator royalties, if any, and realized secondary proceeds were not verified.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:token_and_value_capture:1","claim:bitcoin-puppets:section:token_and_value_capture:2","claim:bitcoin-puppets:section:token_and_value_capture:3"]},"counterfactual":{"body":"A conventional roadmap could have produced more measurable products, but it also would have exposed an anonymous art project to execution promises its audience did not necessarily want. The free mint and anti-roadmap stance let culture compound with little formal obligation. A stronger outcome would preserve that character while publishing verifiable holder distribution, repeated arm’s-length sales and clear stewardship of public surfaces. A weaker outcome would see the meme remain visible while trading concentrates in a few wallets and community infrastructure quietly disappears.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:counterfactual:1","claim:bitcoin-puppets:section:counterfactual:2","claim:bitcoin-puppets:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Pseudonymous leadership and volunteer stewardship create key-person and continuity risk even when inscriptions remain on Bitcoin. Marketplaces can delist, disappear or show stale asks; a floor is only the cheapest visible listing, not proof of a buyer. Copyleft-style remixing strengthens distribution but can also blur which products are official. This review could not verify current holder concentration, unique buyers and sellers, executable bids, repeat sales, creator revenue, legal entity, treasury or the artist’s continuing workload.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:risks_and_unknowns:1","claim:bitcoin-puppets:section:risks_and_unknowns:2","claim:bitcoin-puppets:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Bitcoin Puppets moved from a January 2024 free mint into a prominent Ordinals meme and then into a community-maintained cultural collection. Its no-roadmap stance means the correct lifecycle test is not whether a promised game shipped; it is whether the art remains recognized, community surfaces persist and real collectors still trade. As of August 3, 2026 the artifact and community are active and market observations exist, but liquidity quality is not fully classified. The collection is culturally durable, not proven financially thriving.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:lifecycle:1","claim:bitcoin-puppets:section:lifecycle:2","claim:bitcoin-puppets:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Bitcoin Puppets remains a recognizable Ordinals culture asset whose staying power depends on community creation more than formal utility. Watch active contributors, website stewardship, unique owners, repeated sales across independent venues, executable bids, wallet concentration and whether new works deepen or dilute the core identity. The call improves if broad ownership and repeat collecting persist without incentives. It weakens if market activity becomes wash-like or concentrated, the public hub goes stale or adjacent tokens repeatedly create confusion about holder rights.","as_of":"2026-08-03","claim_ids":["claim:bitcoin-puppets:section:outlook_and_watch:1","claim:bitcoin-puppets:section:outlook_and_watch:2","claim:bitcoin-puppets:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:bitcoin-puppets:launch","type":"collection_launch","date":"2024-01-01","date_precision":"month","description":"Bitcoin Puppets launched as a free-mint Ordinals collection during January 2024.","claim_ids":["claim:bitcoin-puppets:event:launch"]},{"id":"event:bitcoin-puppets:historical-attention","type":"market_attention","date":"2024-04-22","date_precision":"day","description":"nft now documented the collection’s rapid rise and historical market attention.","claim_ids":["claim:bitcoin-puppets:event:historical-attention"]},{"id":"event:bitcoin-puppets:current-observation","type":"current_operations","date":"2026-08-03","date_precision":"day","description":"The community hub, gallery and independent marketplace index remained observable.","claim_ids":["claim:bitcoin-puppets:event:current-observation"]}],"sources":[{"id":"source:bitcoin-puppets:hub","title":"Bitcoin Puppets community hub","url":"https://bitcoinpuppets.community/","publisher":"Bitcoin Puppets Community","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://bitcoinpuppets.community/","content_hash":null,"independence_group":"bitcoin-puppets-community","access_method":"direct_http","direct_http_status":200},{"id":"source:bitcoin-puppets:gallery","title":"Bitcoin Puppets community gallery","url":"https://bitcoinpuppets.community/gallery","publisher":"Bitcoin Puppets Community","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://bitcoinpuppets.community/gallery","content_hash":null,"independence_group":"bitcoin-puppets-community","access_method":"direct_http","direct_http_status":200},{"id":"source:bitcoin-puppets:nftnow","title":"The ultimate guide to Bitcoin Puppets","url":"https://nftnow.com/guides/bitcoin-puppets-ordinals-guide/","publisher":"nft now","published_at":"2024-04-22","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://nftnow.com/guides/bitcoin-puppets-ordinals-guide/","content_hash":null,"independence_group":"nft-now","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:bitcoin-puppets:liquidium","title":"What are Bitcoin Puppets?","url":"https://liquidium.wtf/blog/bitcoin-puppets","publisher":"Liquidium","published_at":"2025-07-09","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"C","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://liquidium.wtf/blog/bitcoin-puppets","content_hash":null,"independence_group":"liquidium","access_method":"direct_http","direct_http_status":200},{"id":"source:bitcoin-puppets:market","title":"Bitcoin Ordinals marketplace","url":"https://ord.net/","publisher":"ORD","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"C","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://ord.net/","content_hash":null,"independence_group":"ord-net","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:bitcoin-puppets:status","field_path":"status.operating_state","assertion":"Bitcoin Puppets remained indexed as a 10,001-piece collection with a live community hub and observable marketplace listings on August 3, 2026.","value":"active_artifact_and_community_without_formal_roadmap","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery","source:bitcoin-puppets:market"],"evidence_locator":"Current community and marketplace surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:outcome","field_path":"outcome.label","assertion":"Bitcoin Puppets sustained a recognizable community through art and meme identity despite rejecting a conventional roadmap, while current liquidity remains thinly measured.","value":"culturally_durable_meme_collection_with_thinly_measured_market","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow","source:bitcoin-puppets:liquidium","source:bitcoin-puppets:market"],"evidence_locator":"Community doctrine, independent history and current market observation.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Bitcoin Puppets comprises 10,001 hand-drawn profile-picture inscriptions on Bitcoin.","value":"Bitcoin Puppets comprises 10,001 hand-drawn profile-picture inscriptions on Bitcoin.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow","source:bitcoin-puppets:liquidium"],"evidence_locator":"Current community description and independent histories.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"The collection was a free mint and rejects a conventional roadmap or guarantees.","value":"The collection was a free mint and rejects a conventional roadmap or guarantees.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:liquidium"],"evidence_locator":"Community doctrine and independent 2025 description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"O.P.I.U.M., honorary works, marketplaces and adjacent tokens are separate from the core collection.","value":"O.P.I.U.M., honorary works, marketplaces and adjacent tokens are separate from the core collection.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow"],"evidence_locator":"Collection history and identity boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Bitcoin Puppets launched in January 2024 after the artist’s earlier O.P.I.U.M. collection.","value":"Bitcoin Puppets launched in January 2024 after the artist’s earlier O.P.I.U.M. collection.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:nftnow","source:bitcoin-puppets:liquidium"],"evidence_locator":"Independent collection histories.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"The collection attracted substantial market attention during 2024.","value":"The collection attracted substantial market attention during 2024.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:nftnow"],"evidence_locator":"Contemporary report; historical only.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Current community and marketplace surfaces remained observable in August 2026.","value":"Current community and marketplace surfaces remained observable in August 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery","source:bitcoin-puppets:market"],"evidence_locator":"Direct current observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"The community explicitly centers art, absurdity and participation instead of a roadmap.","value":"The community explicitly centers art, absurdity and participation instead of a roadmap.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub"],"evidence_locator":"Current community manifesto and FAQ.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"Independent histories connect the collection’s identity to the pseudonymous artist and earlier work.","value":"Independent histories connect the collection’s identity to the pseudonymous artist and earlier work.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:nftnow","source:bitcoin-puppets:liquidium"],"evidence_locator":"Independent historical accounts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Cultural recognition can persist without proving deep liquidity or an operating business.","value":"Cultural recognition can persist without proving deep liquidity or an operating business.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:market","source:bitcoin-puppets:nftnow"],"evidence_locator":"Community and market synthesis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"The project chose a free mint and no-roadmap posture.","value":"The project chose a free mint and no-roadmap posture.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:liquidium"],"evidence_locator":"Community FAQ and independent description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"The collection uses permissive remix language and community curation as distribution.","value":"The collection uses permissive remix language and community curation as distribution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery"],"evidence_locator":"Current license and gallery surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"Minimal promises reduce roadmap risk but leave no conventional service commitment.","value":"Minimal promises reduce roadmap risk but leave no conventional service commitment.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow"],"evidence_locator":"Governance and accountability boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"The project presents the community, not a conventional company, as the continuing operating layer.","value":"The project presents the community, not a conventional company, as the continuing operating layer.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery"],"evidence_locator":"Current community surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Third-party marketplaces and lending products operate separately from the collection.","value":"Third-party marketplaces and lending products operate separately from the collection.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:market","source:bitcoin-puppets:liquidium"],"evidence_locator":"Venue and product boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"A formal entity, payroll, treasury and recurring revenue model were not identified.","value":"A formal entity, payroll, treasury and recurring revenue model were not identified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow","source:bitcoin-puppets:liquidium"],"evidence_locator":"Public-source review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"The core assets are Bitcoin inscriptions and the community does not promise guaranteed utility.","value":"The core assets are Bitcoin inscriptions and the community does not promise guaranteed utility.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow"],"evidence_locator":"Community FAQ and independent guide.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Adjacent fungible tokens or collections are not automatically economic claims on Bitcoin Puppets.","value":"Adjacent fungible tokens or collections are not automatically economic claims on Bitcoin Puppets.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow"],"evidence_locator":"Identity boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Current creator royalties and realized secondary proceeds were not verified.","value":"Current creator royalties and realized secondary proceeds were not verified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:market","source:bitcoin-puppets:hub"],"evidence_locator":"Current evidence review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The no-roadmap stance deliberately avoided conventional product commitments.","value":"The no-roadmap stance deliberately avoided conventional product commitments.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:liquidium"],"evidence_locator":"Project doctrine and independent description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"The community model allowed identity and remixing to remain the primary product.","value":"The community model allowed identity and remixing to remain the primary product.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery","source:bitcoin-puppets:nftnow"],"evidence_locator":"Community and historical evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"Broad holder distribution, repeat sales and stewardship continuity remain incompletely measured.","value":"Broad holder distribution, repeat sales and stewardship continuity remain incompletely measured.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:gallery","source:bitcoin-puppets:market"],"evidence_locator":"Current evidence gap.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Pseudonymous, community-led stewardship creates continuity and accountability risk.","value":"Pseudonymous, community-led stewardship creates continuity and accountability risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:nftnow"],"evidence_locator":"Leadership and operating model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Marketplace listings and quoted floors do not prove executable demand.","value":"Marketplace listings and quoted floors do not prove executable demand.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:market"],"evidence_locator":"Current venue observation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Holder concentration, repeat sales, revenue, legal entity and treasury were not verified.","value":"Holder concentration, repeat sales, revenue, legal entity and treasury were not verified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery","source:bitcoin-puppets:market"],"evidence_locator":"Current-source review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The collection launched as a free mint in January 2024.","value":"The collection launched as a free mint in January 2024.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:liquidium"],"evidence_locator":"Community and independent history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"Community and gallery surfaces remained active in August 2026.","value":"Community and gallery surfaces remained active in August 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery"],"evidence_locator":"Current direct observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Current liquidity quality remains unclassified despite visible listings.","value":"Current liquidity quality remains unclassified despite visible listings.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:market"],"evidence_locator":"Market metric boundary.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Current community surfaces support a culture-led continuing base case.","value":"Current community surfaces support a culture-led continuing base case.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery"],"evidence_locator":"Current community evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"Market health should be tested through repeated independent buyers and executable bids.","value":"Market health should be tested through repeated independent buyers and executable bids.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitcoin-puppets:market","source:bitcoin-puppets:nftnow"],"evidence_locator":"Market-quality rule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current owner breadth, repeat buyers and bid depth require verification.","value":"Current owner breadth, repeat buyers and bid depth require verification.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:bitcoin-puppets:market","source:bitcoin-puppets:gallery"],"evidence_locator":"Forward evidence requirements.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:event:launch","field_path":"events[event:bitcoin-puppets:launch]","assertion":"Bitcoin Puppets launched as a free-mint Ordinals collection during January 2024.","value":"2024-01-01","as_of":"2024-01-01","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:liquidium"],"evidence_locator":"Community FAQ and independent history.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:event:historical-attention","field_path":"events[event:bitcoin-puppets:historical-attention]","assertion":"nft now documented the collection’s rapid rise and historical market attention.","value":"2024-04-22","as_of":"2024-04-22","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:nftnow"],"evidence_locator":"Dated independent guide; prices treated as historical.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitcoin-puppets:event:current-observation","field_path":"events[event:bitcoin-puppets:current-observation]","assertion":"The community hub, gallery and independent marketplace index remained observable.","value":"2026-08-03","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitcoin-puppets:hub","source:bitcoin-puppets:gallery","source:bitcoin-puppets:market"],"evidence_locator":"Direct current observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:07:00Z","next_review_at":"2026-08-10T22:07:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["holder_concentration","unique_buyers_and_sellers","bid_depth","repeat_sales","creator_revenue","legal_entity","treasury","artist_workload"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Bitcoin Puppets, O.P.I.U.M., honorary artworks, Rune Pups, PUPS, marketplaces, lenders and the pseudonymous artist are separate.","metric_boundary":"Asks, floors, bids, completed sales, holders, lending values and adjacent-token prices are distinct measures.","editorial_guardrail":"Do not treat a marketplace floor as liquidity, an adjacent token as holder revenue or a no-roadmap art collection as failed for lacking a game.","explicit_unknowns":["holder_concentration","unique_buyers_and_sellers","bid_depth","repeat_sales","creator_revenue","legal_entity","treasury","artist_workload"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","Lifecycle is evaluated as a finite cultural collection rather than a conventional software startup."]}}');

INSERT INTO _nft_ordinals_depth_wave_d_0103 (slug, canonical_profile) VALUES ('gamma-ordinals-platform', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"ordinals_collection:gamma-ordinals-platform","type":"ordinals_collection","slug":"gamma-ordinals-platform","name":"Gamma Ordinals","aliases":[]},"classification":{"subtype":"Bitcoin inscriptions platform and marketplace","tags":["bitcoin","ordinals","marketplace","launchpad","creator_tools","platform_profile"],"chains":["Bitcoin","Stacks"],"jurisdictions":["Bahamas"]},"status":{"operating_state":"active_creator_platform_and_marketplace","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:status"]},"outcome":{"label":"active_early_mover_platform_with_unverified_current_unit_economics","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:gamma-ordinals-platform:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Gamma Ordinals is a creator platform and marketplace for making, launching, discovering and trading Bitcoin inscriptions. It is stored in Chaindump’s Ordinals corpus for comparison, but it is not itself one collection: creators and their collections are customers or listings, and their performance should not be rolled into Gamma without attribution. Gamma also has Stacks history, while its Ordinals marketplace describes native Bitcoin L1 trading. The current creator terms identify Nassau Machines Inc. as the contracting operator.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:what_it_is:1","claim:gamma-ordinals-platform:section:what_it_is:2","claim:gamma-ordinals-platform:section:what_it_is:3"]},"what_happened":{"body":"Gamma added no-code inscription tooling in February 2023 and released an Ordinals marketplace in March as the new protocol drew rapid attention. Binance Research independently included Gamma’s marketplace release in its early Ordinals timeline. The platform expanded from single and bulk inscriptions into collection mints, launchpad services and native-Bitcoin trading. In 2026 its product and legal pages remained accessible, but this review found no verified current share, creator cohort, trading volume or audited revenue series.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:what_happened:1","claim:gamma-ordinals-platform:section:what_happened:2","claim:gamma-ordinals-platform:section:what_happened:3"]},"why_this_outcome":{"body":"Gamma moved quickly when Ordinals created a technically difficult new market. Its no-code workflow lowered the barrier for creators, while collection minting and a native-Bitcoin marketplace let the same user move from creation to sale without assembling several tools. Independent research confirms Gamma was part of the first marketplace wave. That speed and integrated funnel explain persistence, but early entry does not prove current leadership: competitor growth, Bitcoin market cycles and creator retention can change platform economics.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:why_this_outcome:1","claim:gamma-ordinals-platform:section:why_this_outcome:2","claim:gamma-ordinals-platform:section:why_this_outcome:3"]},"strategic_choices":{"body":"Gamma chose an integrated platform: individual and bulk inscriptions, no-code public mints, collection pages and marketplace trading. It also separated its Ordinals experience from its earlier Stacks marketplace while emphasizing Bitcoin L1 settlement for inscription trades. The creator terms formalize operator control over onboarding and platform rules, even though the underlying inscriptions exist on Bitcoin. This product breadth improves conversion and creator convenience, but it increases the burden to maintain security, moderation, wallets, listings and legal compliance.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:strategic_choices:1","claim:gamma-ordinals-platform:section:strategic_choices:2","claim:gamma-ordinals-platform:section:strategic_choices:3"]},"operating_model":{"body":"Creators use Gamma to inscribe assets, organize collections and run public mints; collectors use the marketplace to discover and trade inscriptions through compatible wallets. Gamma can earn from platform or transaction charges described in applicable interfaces and agreements, while miners earn Bitcoin network fees and creators may set their own sale economics. Those flows must remain separate. Current active creators, repeat minters, unique buyers and sellers, gross merchandise volume, take rate, refunds and operating costs were not verified in reviewed public sources.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:operating_model:1","claim:gamma-ordinals-platform:section:operating_model:2","claim:gamma-ordinals-platform:section:operating_model:3"]},"token_and_value_capture":{"body":"This review found no native Gamma fungible token that represents ownership of the platform. Gamma’s economic opportunity is service and marketplace revenue, while creators receive their own mint proceeds and any creator payments supported by a sale. An inscription bought on Gamma remains the creator’s asset, not equity in Nassau Machines, and third-party collection tokens are not Gamma liabilities. The reviewed terms and product pages did not provide enough current data to calculate realized take rate, annual revenue or profit.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:token_and_value_capture:1","claim:gamma-ordinals-platform:section:token_and_value_capture:2","claim:gamma-ordinals-platform:section:token_and_value_capture:3"]},"counterfactual":{"body":"Gamma could have remained a Stacks-focused NFT venue and missed the native-Bitcoin inscription wave. Moving early into Ordinals gave it creator distribution and a place in the ecosystem’s foundational timeline. A stronger outcome would now show retained creator cohorts, repeat marketplace users, reliable settlement and transparent fee economics rather than relying on first-mover history. A weaker outcome would keep old product pages online while new launches, trades and wallet support migrate elsewhere. Current public evidence is not sufficient to choose between those commercial extremes.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:counterfactual:1","claim:gamma-ordinals-platform:section:counterfactual:2","claim:gamma-ordinals-platform:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Gamma faces marketplace security, wallet integration, listing quality, regulatory and competitive risks. Bitcoin preserves inscriptions, but users still depend on Gamma’s interface, indexing and transaction construction; an onchain asset does not make every web workflow trustless. Creator terms can change and users may confuse creator claims with operator guarantees. This review could not verify custody design across every flow, incident history, current market share, wash-trading controls, retained cohorts, revenue, profitability or the operator’s financial runway.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:risks_and_unknowns:1","claim:gamma-ordinals-platform:section:risks_and_unknowns:2","claim:gamma-ordinals-platform:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Gamma moved from Stacks NFT infrastructure into an early Ordinals inscription service in February 2023, then added a marketplace and broader creator launch tools. Product and legal surfaces remained current enough in 2026 to classify the platform as operating. The right lifecycle call is “active early mover with unverified economics,” not “thriving” based on a 2023 market-share claim or the activity of collections listed there. Each hosted collection needs its own lifecycle profile, and Bitcoin network growth is only context for Gamma demand.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:lifecycle:1","claim:gamma-ordinals-platform:section:lifecycle:2","claim:gamma-ordinals-platform:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Gamma remains a functioning Ordinals creator and marketplace platform, competing on ease of use and its early brand. Watch new public mints, active creators, repeat minters, unique buyers and sellers, completed trade volume, failed transactions, wallet support, security incidents, fee changes and legal updates. The call improves if independent data show retained creators and repeated arm’s-length trades. It weakens if product surfaces stay online but cohorts shrink, major wallets or creators leave, or incident and compliance costs overwhelm marketplace revenue.","as_of":"2026-08-03","claim_ids":["claim:gamma-ordinals-platform:section:outlook_and_watch:1","claim:gamma-ordinals-platform:section:outlook_and_watch:2","claim:gamma-ordinals-platform:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:gamma-ordinals-platform:inscriptions-launch","type":"product_launch","date":"2023-02-08","date_precision":"day","description":"Gamma launched no-code tooling for individual and bulk Ordinals inscriptions.","claim_ids":["claim:gamma-ordinals-platform:event:inscriptions-launch"]},{"id":"event:gamma-ordinals-platform:marketplace-launch","type":"marketplace_launch","date":"2023-03-01","date_precision":"month","description":"Gamma released its native-Bitcoin Ordinals marketplace during March 2023.","claim_ids":["claim:gamma-ordinals-platform:event:marketplace-launch"]},{"id":"event:gamma-ordinals-platform:terms-update","type":"legal_update","date":"2026-04-08","date_precision":"day","description":"Nassau Machines Inc. updated Gamma’s creator terms.","claim_ids":["claim:gamma-ordinals-platform:event:terms-update"]}],"sources":[{"id":"source:gamma-ordinals-platform:launch","title":"Create Ordinal inscriptions on Gamma","url":"https://blog.gamma.io/2023/02/08/create-ordinal-inscriptions-on-gamma","publisher":"Gamma","published_at":"2023-02-08","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://blog.gamma.io/2023/02/08/create-ordinal-inscriptions-on-gamma","content_hash":null,"independence_group":"gamma","access_method":"direct_http","direct_http_status":200},{"id":"source:gamma-ordinals-platform:marketplaces","title":"Ordinals marketplaces","url":"https://stacks.gamma.io/learn/ordinals/marketplaces","publisher":"Gamma","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://stacks.gamma.io/learn/ordinals/marketplaces","content_hash":null,"independence_group":"gamma","access_method":"direct_http","direct_http_status":200},{"id":"source:gamma-ordinals-platform:launchpad","title":"No-code Ordinals launchpad","url":"https://stacks.gamma.io/learn/ordinals/inscriptions/no-code-ordinals-launchpad","publisher":"Gamma","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://stacks.gamma.io/learn/ordinals/inscriptions/no-code-ordinals-launchpad","content_hash":null,"independence_group":"gamma","access_method":"direct_http","direct_http_status":200},{"id":"source:gamma-ordinals-platform:platform","title":"Gamma Ordinals marketplace and creator launchpad","url":"https://ordinals.gamma.io/","publisher":"Gamma","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://ordinals.gamma.io/","content_hash":null,"independence_group":"gamma","access_method":"direct_http","direct_http_status":200},{"id":"source:gamma-ordinals-platform:terms","title":"Gamma creator terms","url":"https://ordinals.gamma.io/terms/creators","publisher":"Nassau Machines Inc.","published_at":"2026-04-08","published_at_precision":"day","accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://ordinals.gamma.io/terms/creators","content_hash":null,"independence_group":"nassau-machines","access_method":"direct_http","direct_http_status":200},{"id":"source:gamma-ordinals-platform:binance","title":"A new era for Bitcoin?","url":"https://research.binance.com/static/pdf/a-new-era-for-bitcoin.pdf","publisher":"Binance Research","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:07:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:07:00Z","access_final_url":"https://research.binance.com/static/pdf/a-new-era-for-bitcoin.pdf","content_hash":null,"independence_group":"binance-research","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:gamma-ordinals-platform:status","field_path":"status.operating_state","assertion":"Gamma maintained an accessible Ordinals marketplace, creator launchpad and creator terms updated in April 2026 as of August 3, 2026.","value":"active_creator_platform_and_marketplace","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:gamma-ordinals-platform:platform","source:gamma-ordinals-platform:terms"],"evidence_locator":"Current product surface and dated legal terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:gamma-ordinals-platform:outcome","field_path":"outcome.label","assertion":"Gamma remains an operating Bitcoin inscriptions platform, but current market share, retained creators, trading depth and